mapper.select:
select id, dict_type, dict_label, dict_value, status, remark from sys_dict
and dict_type like concat('%',#{d.dictType},'%')
and dict_label like concat('%',#{d.dictLabel},'%')
and status = #{d.status}
order by id limit #{offset}, #{pageSize}

mapper.update:
update sys_dict
dict_type = #{d.dictType}, dict_label = #{d.dictLabel}, dict_value = #{d.dictValue}, status = #{d.status}, remark = #{d.remark}
where id = #{id}

mapper.delete:
delete from sys_dict
where id in

